1	// Package service implements the WorkspaceService that orchestrates read queries
2	// and RPC calls to adapter-service.
3	package service
4	
5	import (
6		"context"
7		"encoding/json"
8		"errors"
9		"time"
10	
11		"github.com/tiendv89/workflow-backend/internal/adapter"
12		database2 "github.com/tiendv89/workflow-backend/internal/database"
13		"github.com/tiendv89/workflow-backend/internal/domain"
14	)
15	
16	// DatabaseReader is the read-only interface over the shared PostgreSQL schema.
17	type DatabaseReader interface {
18		ListWorkspaces(ctx context.Context) ([]database2.Workspace, error)
19		GetWorkspace(ctx context.Context, workspaceID string) (database2.Workspace, error)
20		GetWorkspaceUnscoped(ctx context.Context, workspaceID string) (database2.Workspace, error)
21		GetGitHubSource(ctx context.Context, workspaceID string) (database2.WorkspaceGitHubSource, error)
22		ListGitHubSources(ctx context.Context) ([]database2.WorkspaceGitHubSource, error)
23		ListLatestSyncRunsPerWorkspace(ctx context.Context) ([]database2.WorkspaceSyncRun, error)
24		GetLatestSyncRun(ctx context.Context, workspaceID string) (database2.WorkspaceSyncRun, error)
25		ListWorkspaceFeatures(ctx context.Context, workspaceID string) ([]database2.WorkspaceFeature, error)
26		SearchWorkspaceFeatures(ctx context.Context, workspaceID string, filters database2.FeatureSearchFilters) ([]database2.WorkspaceFeature, error)
27		CountWorkspaceFeatures(ctx context.Context, workspaceID string, filters database2.FeatureSearchFilters) (int, error)
28		ListFeatureTaskCounts(ctx context.Context, workspaceID string, featureIDs []string) ([]database2.WorkspaceFeatureTaskCounts, error)
29		GetWorkspaceFeature(ctx context.Context, workspaceID, featureID string) (database2.WorkspaceFeature, error)
30		ListFeatureDocuments(ctx context.Context, workspaceID, featureID string) ([]database2.WorkspaceFeatureDocument, error)
31		ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]database2.WorkspaceTask, error)
32		SearchFeatureTasks(ctx context.Context, workspaceID, featureID string, filters database2.TaskSearchFilters) ([]database2.WorkspaceTask, error)
33		CountFeatureTasks(ctx context.Context, workspaceID, featureID string, filters database2.TaskSearchFilters) (int, error)
34		SearchWorkspaceTasks(ctx context.Context, workspaceID string, filters database2.TaskSearchFilters) ([]database2.WorkspaceTask, error)
35		CountWorkspaceTasks(ctx context.Context, workspaceID string, filters database2.TaskSearchFilters) (int, error)
36		ListWorkspaceTasks(ctx context.Context, workspaceID string) ([]database2.WorkspaceTask, error)
37		GetWorkspaceTask(ctx context.Context, workspaceID, featureID, taskID string) (database2.WorkspaceTask, error)
38		GetWorkspaceTaskByID(ctx context.Context, workspaceID, taskID string) (database2.WorkspaceTask, error)
39		ListActivityEvents(ctx context.Context, workspaceID, featureID, taskID string) ([]database2.WorkspaceActivityEvent, error)
40	}
41	
42	// AdapterCaller issues RPC calls to adapter-service for write operations.
43	type AdapterCaller interface {
44		ImportWorkspace(ctx context.Context, req adapter.ImportRequest) (string, error)
45		SyncWorkspace(ctx context.Context, workspaceID string) error
46	}
47	
48	// WorkspaceService orchestrates reads from PostgreSQL and calls to adapter-service.
49	type WorkspaceService struct {
50		db             DatabaseReader
51		adapter        AdapterCaller
52		staleThreshold time.Duration
53	}
54	
55	// New creates a new WorkspaceService.
56	func New(db DatabaseReader, adapterClient AdapterCaller, staleThreshold time.Duration) *WorkspaceService {
57		return &WorkspaceService{
58			db:             db,
59			adapter:        adapterClient,
60			staleThreshold: staleThreshold,
61		}
62	}
63	
64	// ListWorkspaces returns summary rows for all saved workspaces with source state.
65	func (s *WorkspaceService) ListWorkspaces(ctx context.Context) ([]domain.WorkspaceSummary, error) {
66		rows, err := s.db.ListWorkspaces(ctx)
67		if err != nil {
68			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
69		}
70	
71		// Batch-load latest sync run per workspace to avoid N+1 queries.
72		allRuns, err := s.db.ListLatestSyncRunsPerWorkspace(ctx)
73		if err != nil {
74			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
75		}
76		runMap := make(map[string]database2.WorkspaceSyncRun, len(allRuns))
77		for _, run := range allRuns {
78			runMap[database2.UUIDString(run.WorkspaceID)] = run
79		}
80	
81		// Batch-load GitHub sources to avoid N+1 queries.
82		allSrcs, err := s.db.ListGitHubSources(ctx)
83		if err != nil {
84			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
85		}
86		srcMap := make(map[string]string, len(allSrcs))
87		for _, src := range allSrcs {
88			srcMap[database2.UUIDString(src.WorkspaceID)] = src.RepoURL
89		}
90	
91		out := make([]domain.WorkspaceSummary, 0, len(rows))
92		for _, r := range rows {
93			wsID := database2.UUIDString(r.ID)
94			srcRun, ok := runMap[wsID]
95			var ss domain.SourceState
96			if ok {
97				ss = toSourceState(&srcRun, s.staleThreshold)
98			} else {
99				ss = domain.DeriveSourceState(nil, s.staleThreshold)
100			}
101	
102			repoURL := srcMap[wsID]
103			out = append(out, domain.WorkspaceSummary{
104				ID:          wsID,
105				Name:        r.Name,
106				Slug:        r.Slug,
107				RepoURL:     repoURL,
108				SourceState: ss,
109				UpdatedAt:   r.UpdatedAt.Time,
110			})
111		}
112		return out, nil
113	}
114	
115	// ImportWorkspace calls adapter-service to import/persist a workspace, then
116	// returns the normalized persisted detail from PostgreSQL.
117	//
118	// The post-import fetch uses an unscoped read because the session's accessible
119	// workspace-ID snapshot was taken before this workspace existed. Authorization
120	// is enforced by verifying the persisted organization_id matches the session's
121	// organization_id; any mismatch yields a 404 (DATABASE_NOT_FOUND) to preserve
122	// cross-tenant isolation.
123	func (s *WorkspaceService) ImportWorkspace(ctx context.Context, input domain.ImportInput) (*domain.WorkspaceDetail, domain.SourceError) {
124		workspaceID, err := s.adapter.ImportWorkspace(ctx, adapter.ImportRequest{
125			RepoURL:        input.RepoURL,
126			DefaultBranch:  input.DefaultBranch,
127			Name:           input.Name,
128			OrganizationID: input.OrganizationID,
129		})
130		if err != nil {
131			if se, ok := err.(domain.SourceError); ok {
132				return nil, se
133			}
134			return nil, domain.NewAdapterError(domain.ErrAdapterInternal, err.Error())
135		}
136	
137		ws, dbErr := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
138		if dbErr != nil {
139			if errors.Is(dbErr, database2.ErrNotFound) {
140				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
141			}
142			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, dbErr.Error())
143		}
144	
145		// if ac, ok := authmw.FromContext(ctx); ok && ac.OrganizationID != "" {
146		// 	if database2.UUIDString(ws.OrganizationID) != ac.OrganizationID {
147		// 		return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
148		// 	}
149		// }
150	
151		return s.buildWorkspaceDetail(ctx, ws)
152	}
153	
154	// GetWorkspaceSummary returns only basic workspace information without loading features/tasks.
155	func (s *WorkspaceService) GetWorkspaceSummary(ctx context.Context, workspaceID string) (*domain.WorkspaceSummary, domain.SourceError) {
156		ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
157		if err != nil {
158			if errors.Is(err, database2.ErrNotFound) {
159				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
160			}
161			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
162		}
163	
164		wsID := database2.UUIDString(ws.ID)
165		syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
166		var ss domain.SourceState
167		if errors.Is(err, database2.ErrNotFound) || err != nil {
168			ss = domain.DeriveSourceState(nil, s.staleThreshold)
169		} else {
170			ss = toSourceState(&syncRun, s.staleThreshold)
171		}
172	
173		return &domain.WorkspaceSummary{
174			ID:          wsID,
175			Name:        ws.Name,
176			Slug:        ws.Slug,
177			RepoURL:     s.githubRepoURL(ctx, wsID),
178			SourceState: ss,
179			UpdatedAt:   ws.UpdatedAt.Time,
180		}, domain.SourceError{}
181	}
182	
183	// GetWorkspace returns full workspace detail with features, tasks, and source state.
184	func (s *WorkspaceService) GetWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError) {
185		ws, se := s.fetchWorkspace(ctx, workspaceID)
186		if se != (domain.SourceError{}) {
187			return nil, se
188		}
189		return s.buildWorkspaceDetail(ctx, ws)
190	}
191	
192	// fetchWorkspace resolves a workspace row with scoped access control, falling back
193	// to an unscoped read with org_id authorization for sessions whose accessible-set
194	// snapshot predates the workspace (e.g. immediately after import).
195	func (s *WorkspaceService) fetchWorkspace(ctx context.Context, workspaceID string) (database2.Workspace, domain.SourceError) {
196		ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
197		if err == nil {
198			return ws, domain.SourceError{}
199		}
200		if !errors.Is(err, database2.ErrNotFound) {
201			return database2.Workspace{}, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
202		}
203		// ac, ok := authmw.FromContext(ctx)
204		// if !ok || ac.OrganizationID == "" {
205		// 	return database2.Workspace{}, domain.NewDatabaseNotFound("workspace", workspaceID)
206		// }
207		ws, err = s.db.GetWorkspaceUnscoped(ctx, workspaceID)
208		if err != nil {
209			if errors.Is(err, database2.ErrNotFound) {
210				return database2.Workspace{}, domain.NewDatabaseNotFound("workspace", workspaceID)
211			}
212			return database2.Workspace{}, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
213		}
214		// if database2.UUIDString(ws.OrganizationID) != ac.OrganizationID {
215		// 	return database2.Workspace{}, domain.NewDatabaseNotFound("workspace", workspaceID)
216		// }
217		return ws, domain.SourceError{}
218	}
219	
220	// buildWorkspaceDetail assembles the full WorkspaceDetail from an already-fetched
221	// Workspace row. The caller is responsible for authorizing access to ws.
222	func (s *WorkspaceService) buildWorkspaceDetail(ctx context.Context, ws database2.Workspace) (*domain.WorkspaceDetail, domain.SourceError) {
223		wsID := database2.UUIDString(ws.ID)
224	
225		features, err := s.db.ListWorkspaceFeatures(ctx, wsID)
226		if err != nil {
227			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
228		}
229	
230		tasks, err := s.db.ListWorkspaceTasks(ctx, wsID)
231		if err != nil {
232			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
233		}
234	
235		taskCountsByFeature := countTasksByFeature(tasks)
236	
237		syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
238		var ss domain.SourceState
239		if errors.Is(err, database2.ErrNotFound) || err != nil {
240			ss = domain.DeriveSourceState(nil, s.staleThreshold)
241		} else {
242			ss = toSourceState(&syncRun, s.staleThreshold)
243		}
244	
245		featureSummaries := make([]domain.FeatureSummary, 0, len(features))
246		for _, f := range features {
247			counts := taskCountsByFeature[database2.UUIDString(f.FeatureID)]
248			featureSummaries = append(featureSummaries, domain.FeatureSummary{
249				ID:           database2.UUIDString(f.ID),
250				FeatureID:    database2.UUIDString(f.FeatureID),
251				FeatureName:  f.FeatureName,
252				Title:        f.Title,
253				Status:       derefStr(f.FeatureStatus),
254				CurrentStage: derefStr(f.CurrentStage),
255				Stages:       rawJSONOrNil(f.Stages),
256				UpdatedAt:    f.UpdatedAt.Time,
257				TaskCounts:   counts,
258			})
259		}
260	
261		taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
262		for _, t := range tasks {
263			taskSummaries = append(taskSummaries, toTaskSummary(t))
264		}
265	
266		repoURL := s.githubRepoURL(ctx, wsID)
267		return &domain.WorkspaceDetail{
268			WorkspaceSummary: domain.WorkspaceSummary{
269				ID:          wsID,
270				Name:        ws.Name,
271				Slug:        ws.Slug,
272				RepoURL:     repoURL,
273				SourceState: ss,
274				UpdatedAt:   ws.UpdatedAt.Time,
275			},
276			Features: featureSummaries,
277			Tasks:    taskSummaries,
278		}, domain.SourceError{}
279	}
280	
281	// SyncWorkspace calls adapter-service to re-sync a workspace then returns updated detail.
282	// On sync failure with cached data, returns cached data marked stale.
283	// On sync failure without cached data, returns a structured source error.
284	func (s *WorkspaceService) SyncWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError) {
285		if _, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID); err != nil {
286			if errors.Is(err, database2.ErrNotFound) {
287				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
288			}
289			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
290		}
291	
292		if err := s.adapter.SyncWorkspace(ctx, workspaceID); err != nil {
293			// Sync failed — try to return cached data with stale marker.
294			detail, dbErr := s.GetWorkspace(ctx, workspaceID)
295			if dbErr != (domain.SourceError{}) {
296				// No cached data — return the adapter error.
297				if se, ok := err.(domain.SourceError); ok {
298					return nil, se
299				}
300				return nil, domain.NewAdapterError(domain.ErrAdapterInternal, err.Error())
301			}
302			// Return stale cached data.
303			detail.SourceState.Stale = true
304			if se, ok := err.(domain.SourceError); ok {
305				detail.SourceState.ErrorCode = string(se.Code)
306				detail.SourceState.ErrorMessage = se.Message
307			}
308			return detail, domain.SourceError{}
309		}
310	
311		return s.GetWorkspace(ctx, workspaceID)
312	}
313	
314	// GetFeature returns feature detail with documents, tasks, and activity.
315	func (s *WorkspaceService) GetFeature(ctx context.Context, workspaceID, featureID string) (*domain.FeatureDetail, domain.SourceError) {
316		// Verify workspace exists.
317		ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
318		if err != nil {
319			if errors.Is(err, database2.ErrNotFound) {
320				return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
321			}
322			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
323		}
324		wsID := database2.UUIDString(ws.ID)
325	
326		feat, err := s.db.GetWorkspaceFeature(ctx, wsID, featureID)
327		if err != nil {
