633		for _, a := range activity {
634			activityEvents = append(activityEvents, toActivityEvent(a))
635		}
636	
637		var dependsOn []string
638		if t.DependsOn != nil {
639			_ = json.Unmarshal(t.DependsOn, &dependsOn)
640		}
641		if dependsOn == nil {
642			dependsOn = []string{}
643		}
644	
645		var execution map[string]interface{}
646		if t.Execution != nil {
647			_ = json.Unmarshal(t.Execution, &execution)
648		}
649		execCtx := domain.ExecutionContext{}
650		if execution != nil {
651			if v, ok := execution["actor_type"].(string); ok {
652				execCtx.ActorType = v
653			}
654			if v, ok := execution["last_updated_by"].(string); ok {
655				execCtx.LastUpdatedBy = v
656			}
657			if v, ok := execution["last_updated_at"].(string); ok {
658				execCtx.LastUpdatedAt = v
659			}
660		}
661	
662		summary := toTaskSummary(t)
663		prRefs := parsePRRefs(t.Pr, t.WorkspacePr, summary.Repo)
664		return &domain.TaskDetail{
665			ID:            summary.ID,
666			TaskID:        summary.TaskID,
667			TaskName:      summary.TaskName,
668			FeatureID:     summary.FeatureID,
669			FeatureName:   summary.FeatureName,
670			Title:         summary.Title,
671			Status:        summary.Status,
672			Repo:          summary.Repo,
673			Branch:        summary.Branch,
674			NextAction:    summary.NextAction,
675			IsBlocked:     summary.IsBlocked,
676			BlockedReason: summary.BlockedReason,
677			WorkspaceID:   workspaceID,
678			DependsOn:     dependsOn,
679			Execution:     execCtx,
680			PRRefs:        prRefs,
681			Activity:      activityEvents,
682		}
683	}
