719	func toSourceState(run *database2.WorkspaceSyncRun, threshold time.Duration) domain.SourceState {
720		if run == nil {
721			return domain.DeriveSourceState(nil, threshold)
722		}
723		sr := &domain.SyncRun{
724			ID:          database2.UUIDString(run.ID),
725			WorkspaceID: database2.UUIDString(run.WorkspaceID),
726			Trigger:     run.Trigger,
727			Mode:        run.Mode,
728			Status:      domain.SyncStatus(run.Status),
729			StartedAt:   run.StartedAt.Time,
730		}
731		if run.FinishedAt.Valid {
732			t := run.FinishedAt.Time
733			sr.FinishedAt = &t
734		}
735		if run.CommitSha != nil {
736			sr.CommitSHA = *run.CommitSha
737		}
738		if run.ErrorCode != nil {
739			sr.ErrorCode = *run.ErrorCode
740		}
741		if run.ErrorMessage != nil {
742			sr.ErrorMsg = *run.ErrorMessage
743		}
744		return domain.DeriveSourceState(sr, threshold)
745	}
