826		for _, t := range tasks {
827			featureID := database2.UUIDString(t.FeatureID)
828			current := counts[featureID]
829			current.Total++
830			if t.Status != nil {
831				switch *t.Status {
832				case "done":
833					current.Done++
834				case "in_progress":
835					current.InProgress++
836				case "blocked":
837					current.Blocked++
838				case "ready":
839					current.Ready++
840				case "todo":
841					current.Todo++
842				}
843			}
844			counts[featureID] = current
845		}
846		return counts
847	}
