871	func parsePRRefs(prData, workspacePRData []byte, repo string) []domain.PullRequestRef {
872		var refs []domain.PullRequestRef
873	
874		var pr map[string]interface{}
875		if prData != nil {
876			if json.Unmarshal(prData, &pr) == nil {
877				if url, ok := pr["url"].(string); ok && url != "" {
878					status, _ := pr["status"].(string)
879					refs = append(refs, domain.PullRequestRef{
880						Label:  "Implementation PR",
881						URL:    url,
882						Status: status,
883						Repo:   repo,
884					})
885				}
886			}
887		}
888	
889		var wsPR map[string]interface{}
890		if workspacePRData != nil {
891			if json.Unmarshal(workspacePRData, &wsPR) == nil {
892				if url, ok := wsPR["url"].(string); ok && url != "" {
893					status, _ := wsPR["status"].(string)
894					refs = append(refs, domain.PullRequestRef{
895						Label:  "Workspace PR",
896						URL:    url,
897						Status: status,
898						Repo:   "management-repo",
899					})
900				}
901			}
902		}
903		return refs
904	}
905	
906	func derefStr(s *string) string {
907		if s == nil {
908			return ""
909		}
910		return *s
911	}
912	
913	func rawJSONOrNil(raw json.RawMessage) json.RawMessage {
914		if len(raw) == 0 || string(raw) == "null" || !json.Valid(raw) {
915			return nil
916		}
917		return raw
918	}
