// Package service implements the WorkspaceService that orchestrates read queries
// and RPC calls to adapter-service.
package service

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/tiendv89/workflow-backend/internal/adapter"
	database2 "github.com/tiendv89/workflow-backend/internal/database"
	"github.com/tiendv89/workflow-backend/internal/domain"
)

// DatabaseReader is the read-only interface over the shared PostgreSQL schema.
type DatabaseReader interface {
	ListWorkspaces(ctx context.Context) ([]database2.Workspace, error)
	GetWorkspace(ctx context.Context, workspaceID string) (database2.Workspace, error)
	GetWorkspaceUnscoped(ctx context.Context, workspaceID string) (database2.Workspace, error)
	GetGitHubSource(ctx context.Context, workspaceID string) (database2.WorkspaceGitHubSource, error)
	ListGitHubSources(ctx context.Context) ([]database2.WorkspaceGitHubSource, error)
	ListLatestSyncRunsPerWorkspace(ctx context.Context) ([]database2.WorkspaceSyncRun, error)
	GetLatestSyncRun(ctx context.Context, workspaceID string) (database2.WorkspaceSyncRun, error)
	ListWorkspaceFeatures(ctx context.Context, workspaceID string) ([]database2.WorkspaceFeature, error)
	SearchWorkspaceFeatures(ctx context.Context, workspaceID string, filters database2.FeatureSearchFilters) ([]database2.WorkspaceFeature, error)
	CountWorkspaceFeatures(ctx context.Context, workspaceID string, filters database2.FeatureSearchFilters) (int, error)
	ListFeatureTaskCounts(ctx context.Context, workspaceID string, featureIDs []string) ([]database2.WorkspaceFeatureTaskCounts, error)
	GetWorkspaceFeature(ctx context.Context, workspaceID, featureID string) (database2.WorkspaceFeature, error)
	ListFeatureDocuments(ctx context.Context, workspaceID, featureID string) ([]database2.WorkspaceFeatureDocument, error)
	ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]database2.WorkspaceTask, error)
	SearchFeatureTasks(ctx context.Context, workspaceID, featureID string, filters database2.TaskSearchFilters) ([]database2.WorkspaceTask, error)
	CountFeatureTasks(ctx context.Context, workspaceID, featureID string, filters database2.TaskSearchFilters) (int, error)
	SearchWorkspaceTasks(ctx context.Context, workspaceID string, filters database2.TaskSearchFilters) ([]database2.WorkspaceTask, error)
	CountWorkspaceTasks(ctx context.Context, workspaceID string, filters database2.TaskSearchFilters) (int, error)
	ListWorkspaceTasks(ctx context.Context, workspaceID string) ([]database2.WorkspaceTask, error)
	GetWorkspaceTask(ctx context.Context, workspaceID, featureID, taskID string) (database2.WorkspaceTask, error)
	GetWorkspaceTaskByID(ctx context.Context, workspaceID, taskID string) (database2.WorkspaceTask, error)
	ListActivityEvents(ctx context.Context, workspaceID, featureID, taskID string) ([]database2.WorkspaceActivityEvent, error)
}

// AdapterCaller issues RPC calls to adapter-service for write operations.
type AdapterCaller interface {
	ImportWorkspace(ctx context.Context, req adapter.ImportRequest) (string, error)
	SyncWorkspace(ctx context.Context, workspaceID string) error
}

// WorkspaceService orchestrates reads from PostgreSQL and calls to adapter-service.
type WorkspaceService struct {
	db             DatabaseReader
	adapter        AdapterCaller
	staleThreshold time.Duration
}

// New creates a new WorkspaceService.
func New(db DatabaseReader, adapterClient AdapterCaller, staleThreshold time.Duration) *WorkspaceService {
	return &WorkspaceService{
		db:             db,
		adapter:        adapterClient,
		staleThreshold: staleThreshold,
	}
}

// ListWorkspaces returns summary rows for all saved workspaces with source state.
func (s *WorkspaceService) ListWorkspaces(ctx context.Context) ([]domain.WorkspaceSummary, error) {
	rows, err := s.db.ListWorkspaces(ctx)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	// Batch-load latest sync run per workspace to avoid N+1 queries.
	allRuns, err := s.db.ListLatestSyncRunsPerWorkspace(ctx)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	runMap := make(map[string]database2.WorkspaceSyncRun, len(allRuns))
	for _, run := range allRuns {
		runMap[database2.UUIDString(run.WorkspaceID)] = run
	}

	// Batch-load GitHub sources to avoid N+1 queries.
	allSrcs, err := s.db.ListGitHubSources(ctx)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	srcMap := make(map[string]string, len(allSrcs))
	for _, src := range allSrcs {
		srcMap[database2.UUIDString(src.WorkspaceID)] = src.RepoURL
	}

	out := make([]domain.WorkspaceSummary, 0, len(rows))
	for _, r := range rows {
		wsID := database2.UUIDString(r.ID)
		srcRun, ok := runMap[wsID]
		var ss domain.SourceState
		if ok {
			ss = toSourceState(&srcRun, s.staleThreshold)
		} else {
			ss = domain.DeriveSourceState(nil, s.staleThreshold)
		}

		repoURL := srcMap[wsID]
		out = append(out, domain.WorkspaceSummary{
			ID:          wsID,
			Name:        r.Name,
			Slug:        r.Slug,
			RepoURL:     repoURL,
			SourceState: ss,
			UpdatedAt:   r.UpdatedAt.Time,
		})
	}
	return out, nil
}

// ImportWorkspace calls adapter-service to import/persist a workspace, then
// returns the normalized persisted detail from PostgreSQL.
//
// The post-import fetch uses an unscoped read because the session's accessible
// workspace-ID snapshot was taken before this workspace existed. Authorization
// is enforced by verifying the persisted organization_id matches the session's
// organization_id; any mismatch yields a 404 (DATABASE_NOT_FOUND) to preserve
// cross-tenant isolation.
func (s *WorkspaceService) ImportWorkspace(ctx context.Context, input domain.ImportInput) (*domain.WorkspaceDetail, domain.SourceError) {
	workspaceID, err := s.adapter.ImportWorkspace(ctx, adapter.ImportRequest{
		RepoURL:        input.RepoURL,
		DefaultBranch:  input.DefaultBranch,
		Name:           input.Name,
		OrganizationID: input.OrganizationID,
	})
	if err != nil {
		if se, ok := err.(domain.SourceError); ok {
			return nil, se
		}
		return nil, domain.NewAdapterError(domain.ErrAdapterInternal, err.Error())
	}

	ws, dbErr := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if dbErr != nil {
		if errors.Is(dbErr, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, dbErr.Error())
	}

	// if ac, ok := authmw.FromContext(ctx); ok && ac.OrganizationID != "" {
	// 	if database2.UUIDString(ws.OrganizationID) != ac.OrganizationID {
	// 		return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
	// 	}
	// }

	return s.buildWorkspaceDetail(ctx, ws)
}

// GetWorkspaceSummary returns only basic workspace information without loading features/tasks.
func (s *WorkspaceService) GetWorkspaceSummary(ctx context.Context, workspaceID string) (*domain.WorkspaceSummary, domain.SourceError) {
	ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	wsID := database2.UUIDString(ws.ID)
	syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
	var ss domain.SourceState
	if errors.Is(err, database2.ErrNotFound) || err != nil {
		ss = domain.DeriveSourceState(nil, s.staleThreshold)
	} else {
		ss = toSourceState(&syncRun, s.staleThreshold)
	}

	return &domain.WorkspaceSummary{
		ID:          wsID,
		Name:        ws.Name,
		Slug:        ws.Slug,
		RepoURL:     s.githubRepoURL(ctx, wsID),
		SourceState: ss,
		UpdatedAt:   ws.UpdatedAt.Time,
	}, domain.SourceError{}
}

// GetWorkspace returns full workspace detail with features, tasks, and source state.
func (s *WorkspaceService) GetWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError) {
	ws, se := s.fetchWorkspace(ctx, workspaceID)
	if se != (domain.SourceError{}) {
		return nil, se
	}
	return s.buildWorkspaceDetail(ctx, ws)
}

// fetchWorkspace resolves a workspace row with scoped access control, falling back
// to an unscoped read with org_id authorization for sessions whose accessible-set
// snapshot predates the workspace (e.g. immediately after import).
func (s *WorkspaceService) fetchWorkspace(ctx context.Context, workspaceID string) (database2.Workspace, domain.SourceError) {
	ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err == nil {
		return ws, domain.SourceError{}
	}
	if !errors.Is(err, database2.ErrNotFound) {
		return database2.Workspace{}, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	// ac, ok := authmw.FromContext(ctx)
	// if !ok || ac.OrganizationID == "" {
	// 	return database2.Workspace{}, domain.NewDatabaseNotFound("workspace", workspaceID)
	// }
	ws, err = s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return database2.Workspace{}, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return database2.Workspace{}, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	// if database2.UUIDString(ws.OrganizationID) != ac.OrganizationID {
	// 	return database2.Workspace{}, domain.NewDatabaseNotFound("workspace", workspaceID)
	// }
	return ws, domain.SourceError{}
}

// buildWorkspaceDetail assembles the full WorkspaceDetail from an already-fetched
// Workspace row. The caller is responsible for authorizing access to ws.
func (s *WorkspaceService) buildWorkspaceDetail(ctx context.Context, ws database2.Workspace) (*domain.WorkspaceDetail, domain.SourceError) {
	wsID := database2.UUIDString(ws.ID)

	features, err := s.db.ListWorkspaceFeatures(ctx, wsID)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	tasks, err := s.db.ListWorkspaceTasks(ctx, wsID)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	taskCountsByFeature := countTasksByFeature(tasks)

	syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
	var ss domain.SourceState
	if errors.Is(err, database2.ErrNotFound) || err != nil {
		ss = domain.DeriveSourceState(nil, s.staleThreshold)
	} else {
		ss = toSourceState(&syncRun, s.staleThreshold)
	}

	featureSummaries := make([]domain.FeatureSummary, 0, len(features))
	for _, f := range features {
		counts := taskCountsByFeature[database2.UUIDString(f.FeatureID)]
		featureSummaries = append(featureSummaries, domain.FeatureSummary{
			ID:           database2.UUIDString(f.ID),
			FeatureID:    database2.UUIDString(f.FeatureID),
			FeatureName:  f.FeatureName,
			Title:        f.Title,
			Status:       derefStr(f.FeatureStatus),
			CurrentStage: derefStr(f.CurrentStage),
			Stages:       rawJSONOrNil(f.Stages),
			UpdatedAt:    f.UpdatedAt.Time,
			TaskCounts:   counts,
		})
	}

	taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
	for _, t := range tasks {
		taskSummaries = append(taskSummaries, toTaskSummary(t))
	}

	repoURL := s.githubRepoURL(ctx, wsID)
	return &domain.WorkspaceDetail{
		WorkspaceSummary: domain.WorkspaceSummary{
			ID:          wsID,
			Name:        ws.Name,
			Slug:        ws.Slug,
			RepoURL:     repoURL,
			SourceState: ss,
			UpdatedAt:   ws.UpdatedAt.Time,
		},
		Features: featureSummaries,
		Tasks:    taskSummaries,
	}, domain.SourceError{}
}

// SyncWorkspace calls adapter-service to re-sync a workspace then returns updated detail.
// On sync failure with cached data, returns cached data marked stale.
// On sync failure without cached data, returns a structured source error.
func (s *WorkspaceService) SyncWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError) {
	if _, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID); err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	if err := s.adapter.SyncWorkspace(ctx, workspaceID); err != nil {
		// Sync failed — try to return cached data with stale marker.
		detail, dbErr := s.GetWorkspace(ctx, workspaceID)
		if dbErr != (domain.SourceError{}) {
			// No cached data — return the adapter error.
			if se, ok := err.(domain.SourceError); ok {
				return nil, se
			}
			return nil, domain.NewAdapterError(domain.ErrAdapterInternal, err.Error())
		}
		// Return stale cached data.
		detail.SourceState.Stale = true
		if se, ok := err.(domain.SourceError); ok {
			detail.SourceState.ErrorCode = string(se.Code)
			detail.SourceState.ErrorMessage = se.Message
		}
		return detail, domain.SourceError{}
	}

	return s.GetWorkspace(ctx, workspaceID)
}

// GetFeature returns feature detail with documents, tasks, and activity.
func (s *WorkspaceService) GetFeature(ctx context.Context, workspaceID, featureID string) (*domain.FeatureDetail, domain.SourceError) {
	// Verify workspace exists.
	ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	wsID := database2.UUIDString(ws.ID)

	feat, err := s.db.GetWorkspaceFeature(ctx, wsID, featureID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("feature", featureID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	featureUUID := database2.UUIDString(feat.FeatureID)

	docs, err := s.db.ListFeatureDocuments(ctx, wsID, featureUUID)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	tasks, err := s.db.ListFeatureTasks(ctx, wsID, featureUUID)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	activity, err := s.db.ListActivityEvents(ctx, wsID, featureUUID, "")
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
	var ss domain.SourceState
	if errors.Is(err, database2.ErrNotFound) || err != nil {
		ss = domain.DeriveSourceState(nil, s.staleThreshold)
	} else {
		ss = toSourceState(&syncRun, s.staleThreshold)
	}

	counts := countTasks(tasks)
	docLinks := make([]domain.DocumentLink, 0, len(docs))
	for _, d := range docs {
		docLinks = append(docLinks, domain.DocumentLink{
			DocumentType: d.DocumentType,
			SourcePath:   d.SourcePath,
			URL:          derefStr(d.URL),
		})
	}

	taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
	for _, t := range tasks {
		taskSummaries = append(taskSummaries, toTaskSummary(t))
	}

	activityEvents := make([]domain.ActivityEvent, 0, len(activity))
	for _, a := range activity {
		activityEvents = append(activityEvents, toActivityEvent(a))
	}

	return &domain.FeatureDetail{
		FeatureSummary: domain.FeatureSummary{
			ID:           database2.UUIDString(feat.ID),
			FeatureID:    database2.UUIDString(feat.FeatureID),
			FeatureName:  feat.FeatureName,
			Title:        feat.Title,
			Status:       derefStr(feat.FeatureStatus),
			CurrentStage: derefStr(feat.CurrentStage),
			Stages:       rawJSONOrNil(feat.Stages),
			UpdatedAt:    feat.UpdatedAt.Time,
			TaskCounts:   counts,
		},
		WorkspaceID: workspaceID,
		Documents:   docLinks,
		Tasks:       taskSummaries,
		Activity:    activityEvents,
		SourceState: ss,
	}, domain.SourceError{}
}

// ListFeatureTasks returns task summaries for all tasks in a feature.
func (s *WorkspaceService) ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]domain.TaskSummary, domain.SourceError) {
	feat, err := s.db.GetWorkspaceFeature(ctx, workspaceID, featureID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("feature", featureID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	tasks, err := s.db.ListFeatureTasks(ctx, workspaceID, database2.UUIDString(feat.FeatureID))
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	out := make([]domain.TaskSummary, 0, len(tasks))
	for _, t := range tasks {
		out = append(out, toTaskSummary(t))
	}
	return out, domain.SourceError{}
}

// SearchTasks returns paged task summaries for a feature filtered by search/task_id/title/status/repo.
func (s *WorkspaceService) SearchTasks(ctx context.Context, workspaceID, featureID string, query domain.TaskSearchQuery) (*domain.PagedTasks, domain.SourceError) {
	if query.Page == 0 {
		query.Page = 1
	}
	if query.Page < 1 {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "page must be greater than or equal to 1")
	}
	if query.Limit < 0 {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "limit must be greater than or equal to 0")
	}
	if query.Sort != "" && !isValidTaskSearchSort(query.Sort) {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "sort must be one of task_id_asc, task_id_desc, title_asc, title_desc, status_asc, status_desc, repo_asc, repo_desc, updated_at_asc, updated_at_desc, time_asc, time_desc, createdAt, -createdAt")
	}

	feat, err := s.db.GetWorkspaceFeature(ctx, workspaceID, featureID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("feature", featureID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	featureUUID := database2.UUIDString(feat.FeatureID)

	filters := database2.TaskSearchFilters{
		TaskID: query.TaskID,
		Title:  query.Title,
		Status: query.Status,
		Repo:   query.Repo,
		Sort:   query.Sort,
		Page:   query.Page,
		Limit:  query.Limit,
	}
	tasks, err := s.db.SearchFeatureTasks(ctx, workspaceID, featureUUID, filters)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	total, err := s.db.CountFeatureTasks(ctx, workspaceID, featureUUID, filters)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	items := make([]domain.TaskSummary, 0, len(tasks))
	for _, t := range tasks {
		items = append(items, toTaskSummary(t))
	}
	return &domain.PagedTasks{Items: items, Total: total, Page: query.Page, Limit: query.Limit}, domain.SourceError{}
}

// SearchWorkspaceTasks returns paged task summaries for a workspace filtered by search/task_id/title/status/repo.
func (s *WorkspaceService) SearchWorkspaceTasks(ctx context.Context, workspaceID string, query domain.TaskSearchQuery) (*domain.PagedTasks, domain.SourceError) {
	if query.Page == 0 {
		query.Page = 1
	}
	if query.Page < 1 {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "page must be greater than or equal to 1")
	}
	if query.Limit < 0 {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "limit must be greater than or equal to 0")
	}
	if query.Sort != "" && !isValidTaskSearchSort(query.Sort) {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "sort must be one of task_id_asc, task_id_desc, title_asc, title_desc, status_asc, status_desc, repo_asc, repo_desc, updated_at_asc, updated_at_desc, time_asc, time_desc, createdAt, -createdAt")
	}

	filters := database2.TaskSearchFilters{
		TaskID: query.TaskID,
		Title:  query.Title,
		Status: query.Status,
		Repo:   query.Repo,
		Sort:   query.Sort,
		Page:   query.Page,
		Limit:  query.Limit,
	}
	tasks, err := s.db.SearchWorkspaceTasks(ctx, workspaceID, filters)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	total, err := s.db.CountWorkspaceTasks(ctx, workspaceID, filters)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	items := make([]domain.TaskSummary, 0, len(tasks))
	for _, t := range tasks {
		items = append(items, toTaskSummary(t))
	}
	return &domain.PagedTasks{Items: items, Total: total, Page: query.Page, Limit: query.Limit}, domain.SourceError{}
}

// SearchFeatures returns paged feature summaries for a workspace filtered by search/title/status.
func (s *WorkspaceService) SearchFeatures(ctx context.Context, workspaceID string, query domain.FeatureSearchQuery) (*domain.PagedFeatures, domain.SourceError) {
	if query.Page == 0 {
		query.Page = 1
	}
	if query.Page < 1 {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "page must be greater than or equal to 1")
	}
	if query.Limit < 0 {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "limit must be greater than or equal to 0")
	}
	if query.Sort != "" && !isValidSearchSort(query.Sort) {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "sort must be one of title_asc, title_desc, status_asc, status_desc, updated_at_asc, updated_at_desc, time_asc, time_desc, createdAt, -createdAt")
	}

	filters := database2.FeatureSearchFilters{
		Title:  query.Title,
		Status: query.Status,
		Sort:   query.Sort,
		Page:   query.Page,
		Limit:  query.Limit,
	}
	features, err := s.db.SearchWorkspaceFeatures(ctx, workspaceID, filters)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	total, err := s.db.CountWorkspaceFeatures(ctx, workspaceID, filters)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	taskCountsByFeature := map[string]domain.TaskCounts{}
	if len(features) > 0 {
		countRows, err := s.db.ListFeatureTaskCounts(ctx, workspaceID, featureIDs(features))
		if err != nil {
			return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
		}
		taskCountsByFeature = taskCountsFromRows(countRows)
	}

	items := make([]domain.FeatureSummary, 0, len(features))
	for _, f := range features {
		counts := taskCountsByFeature[database2.UUIDString(f.FeatureID)]
		items = append(items, domain.FeatureSummary{
			ID:           database2.UUIDString(f.ID),
			FeatureID:    database2.UUIDString(f.FeatureID),
			FeatureName:  f.FeatureName,
			Title:        f.Title,
			Status:       derefStr(f.FeatureStatus),
			CurrentStage: derefStr(f.CurrentStage),
			Stages:       rawJSONOrNil(f.Stages),
			UpdatedAt:    f.UpdatedAt.Time,
			TaskCounts:   counts,
		})
	}
	return &domain.PagedFeatures{Items: items, Total: total, Page: query.Page, Limit: query.Limit}, domain.SourceError{}
}

// GetTask returns full task detail including activity.
func (s *WorkspaceService) GetTask(ctx context.Context, workspaceID, featureID, taskID string) (*domain.TaskDetail, domain.SourceError) {
	ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	wsID := database2.UUIDString(ws.ID)

	feat, err := s.db.GetWorkspaceFeature(ctx, wsID, featureID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("feature", featureID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	t, err := s.db.GetWorkspaceTask(ctx, wsID, database2.UUIDString(feat.FeatureID), taskID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("task", taskID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	activity, err := s.db.ListActivityEvents(ctx, wsID, database2.UUIDString(t.FeatureID), database2.UUIDString(t.TaskID))
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	return taskDetailFromRow(workspaceID, t, activity), domain.SourceError{}
}

// GetWorkspaceTask returns full task detail for a task in a workspace.
func (s *WorkspaceService) GetWorkspaceTask(ctx context.Context, workspaceID, taskID string) (*domain.TaskDetail, domain.SourceError) {
	ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	wsID := database2.UUIDString(ws.ID)

	t, err := s.db.GetWorkspaceTaskByID(ctx, wsID, taskID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("task", taskID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	activity, err := s.db.ListActivityEvents(ctx, wsID, database2.UUIDString(t.FeatureID), database2.UUIDString(t.TaskID))
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	return taskDetailFromRow(workspaceID, t, activity), domain.SourceError{}
}

func taskDetailFromRow(workspaceID string, t database2.WorkspaceTask, activity []database2.WorkspaceActivityEvent) *domain.TaskDetail {
	activityEvents := make([]domain.ActivityEvent, 0, len(activity))
	for _, a := range activity {
		activityEvents = append(activityEvents, toActivityEvent(a))
	}

	var dependsOn []string
	if t.DependsOn != nil {
		_ = json.Unmarshal(t.DependsOn, &dependsOn)
	}
	if dependsOn == nil {
		dependsOn = []string{}
	}

	var execution map[string]interface{}
	if t.Execution != nil {
		_ = json.Unmarshal(t.Execution, &execution)
	}
	execCtx := domain.ExecutionContext{}
	if execution != nil {
		if v, ok := execution["actor_type"].(string); ok {
			execCtx.ActorType = v
		}
		if v, ok := execution["last_updated_by"].(string); ok {
			execCtx.LastUpdatedBy = v
		}
		if v, ok := execution["last_updated_at"].(string); ok {
			execCtx.LastUpdatedAt = v
		}
	}

	summary := toTaskSummary(t)
	prRefs := parsePRRefs(t.Pr, t.WorkspacePr, summary.Repo)
	return &domain.TaskDetail{
		ID:            summary.ID,
		TaskID:        summary.TaskID,
		TaskName:      summary.TaskName,
		FeatureID:     summary.FeatureID,
		FeatureName:   summary.FeatureName,
		Title:         summary.Title,
		Status:        summary.Status,
		Repo:          summary.Repo,
		Branch:        summary.Branch,
		NextAction:    summary.NextAction,
		IsBlocked:     summary.IsBlocked,
		BlockedReason: summary.BlockedReason,
		WorkspaceID:   workspaceID,
		DependsOn:     dependsOn,
		Execution:     execCtx,
		PRRefs:        prRefs,
		Activity:      activityEvents,
	}
}

// ListActivity returns activity events for a workspace.
func (s *WorkspaceService) ListActivity(ctx context.Context, workspaceID string, scope domain.ActivityScope) ([]domain.ActivityEvent, domain.SourceError) {
	ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	wsID := database2.UUIDString(ws.ID)

	events, err := s.db.ListActivityEvents(ctx, wsID, scope.FeatureID, scope.TaskID)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	out := make([]domain.ActivityEvent, 0, len(events))
	for _, a := range events {
		out = append(out, toActivityEvent(a))
	}
	return out, domain.SourceError{}
}

// githubRepoURL fetches the GitHub repo URL for a workspace from workspace_github_sources.
func (s *WorkspaceService) githubRepoURL(ctx context.Context, workspaceID string) string {
	src, err := s.db.GetGitHubSource(ctx, workspaceID)
	if err != nil {
		return ""
	}
	return src.RepoURL
}

// --- conversion helpers ---

func toSourceState(run *database2.WorkspaceSyncRun, threshold time.Duration) domain.SourceState {
	if run == nil {
		return domain.DeriveSourceState(nil, threshold)
	}
	sr := &domain.SyncRun{
		ID:          database2.UUIDString(run.ID),
		WorkspaceID: database2.UUIDString(run.WorkspaceID),
		Trigger:     run.Trigger,
		Mode:        run.Mode,
		Status:      domain.SyncStatus(run.Status),
		StartedAt:   run.StartedAt.Time,
	}
	if run.FinishedAt.Valid {
		t := run.FinishedAt.Time
		sr.FinishedAt = &t
	}
	if run.CommitSha != nil {
		sr.CommitSHA = *run.CommitSha
	}
	if run.ErrorCode != nil {
		sr.ErrorCode = *run.ErrorCode
	}
	if run.ErrorMessage != nil {
		sr.ErrorMsg = *run.ErrorMessage
	}
	return domain.DeriveSourceState(sr, threshold)
}

func toTaskSummary(t database2.WorkspaceTask) domain.TaskSummary {
	isBlocked := t.Status != nil && *t.Status == "blocked"
	return domain.TaskSummary{
		ID:            database2.UUIDString(t.ID),
		TaskID:        database2.UUIDString(t.TaskID),
		TaskName:      t.TaskName,
		FeatureID:     database2.UUIDString(t.FeatureID),
		FeatureName:   t.FeatureName,
		Title:         t.Title,
		Status:        derefStr(t.Status),
		Repo:          derefStr(t.Repo),
		Branch:        derefStr(t.Branch),
		IsBlocked:     isBlocked,
		BlockedReason: derefStr(t.BlockedReason),
		Pr:            rawJSONOrNil(t.Pr),
		WorkspacePr:   rawJSONOrNil(t.WorkspacePr),
	}
}

func toActivityEvent(a database2.WorkspaceActivityEvent) domain.ActivityEvent {
	e := domain.ActivityEvent{
		Action:    derefStr(a.Action),
		Scope:     a.ScopeType,
		Actor:     derefStr(a.Actor),
		Note:      derefStr(a.Note),
		FeatureID: database2.UUIDString(a.FeatureID),
		TaskID:    database2.UUIDString(a.TaskID),
	}
	if a.OccurredAt != nil {
		if t, err := time.Parse(time.RFC3339, *a.OccurredAt); err == nil {
			e.OccurredAt = t
		}
	}
	return e
}

func isValidSearchSort(sort string) bool {
	switch sort {
	case "title_asc", "title_desc", "status_asc", "status_desc", "updated_at_asc", "updated_at_desc", "time_asc", "time_desc", "createdAt", "-createdAt":
		return true
	default:
		return false
	}
}

func isValidTaskSearchSort(sort string) bool {
	switch sort {
	case "task_id_asc", "task_id_desc", "title_asc", "title_desc", "status_asc", "status_desc", "repo_asc", "repo_desc", "updated_at_asc", "updated_at_desc", "time_asc", "time_desc", "createdAt", "-createdAt":
		return true
	default:
		return false
	}
}

func featureIDs(features []database2.WorkspaceFeature) []string {
	ids := make([]string, 0, len(features))
	for _, feature := range features {
		ids = append(ids, database2.UUIDString(feature.FeatureID))
	}
	return ids
}

func taskCountsFromRows(rows []database2.WorkspaceFeatureTaskCounts) map[string]domain.TaskCounts {
	counts := make(map[string]domain.TaskCounts, len(rows))
	for _, row := range rows {
		counts[database2.UUIDString(row.FeatureID)] = domain.TaskCounts{
			Total:      int(row.Total),
			Done:       int(row.Done),
			InProgress: int(row.InProgress),
			Blocked:    int(row.Blocked),
			Ready:      int(row.Ready),
			Todo:       int(row.Todo),
		}
	}
	return counts
}

func countTasksByFeature(tasks []database2.WorkspaceTask) map[string]domain.TaskCounts {
	counts := make(map[string]domain.TaskCounts, len(tasks))
	for _, t := range tasks {
		featureID := database2.UUIDString(t.FeatureID)
		current := counts[featureID]
		current.Total++
		if t.Status != nil {
			switch *t.Status {
			case "done":
				current.Done++
			case "in_progress":
				current.InProgress++
			case "blocked":
				current.Blocked++
			case "ready":
				current.Ready++
			case "todo":
				current.Todo++
			}
		}
		counts[featureID] = current
	}
	return counts
}

func countTasks(tasks []database2.WorkspaceTask) domain.TaskCounts {
	var counts domain.TaskCounts
	for _, t := range tasks {
		counts.Total++
		if t.Status != nil {
			switch *t.Status {
			case "done":
				counts.Done++
			case "in_progress":
				counts.InProgress++
			case "blocked":
				counts.Blocked++
			case "ready":
				counts.Ready++
			case "todo":
				counts.Todo++
			}
		}
	}
	return counts
}

func parsePRRefs(prData, workspacePRData []byte, repo string) []domain.PullRequestRef {
	var refs []domain.PullRequestRef

	var pr map[string]interface{}
	if prData != nil {
		if json.Unmarshal(prData, &pr) == nil {
			if url, ok := pr["url"].(string); ok && url != "" {
				status, _ := pr["status"].(string)
				refs = append(refs, domain.PullRequestRef{
					Label:  "Implementation PR",
					URL:    url,
					Status: status,
					Repo:   repo,
				})
			}
		}
	}

	var wsPR map[string]interface{}
	if workspacePRData != nil {
		if json.Unmarshal(workspacePRData, &wsPR) == nil {
			if url, ok := wsPR["url"].(string); ok && url != "" {
				status, _ := wsPR["status"].(string)
				refs = append(refs, domain.PullRequestRef{
					Label:  "Workspace PR",
					URL:    url,
					Status: status,
					Repo:   "management-repo",
				})
			}
		}
	}
	return refs
}

func derefStr(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func rawJSONOrNil(raw json.RawMessage) json.RawMessage {
	if len(raw) == 0 || string(raw) == "null" || !json.Valid(raw) {
		return nil
	}
	return raw
}

package domain

import (
	"encoding/json"
	"time"
)

// SourceState describes the freshness and error state of a workspace's data.
type SourceState struct {
	Stale        bool       `json:"stale"`
	LastSyncedAt *time.Time `json:"last_synced_at,omitempty"`
	ErrorCode    string     `json:"error_code,omitempty"`
	ErrorMessage string     `json:"error_message,omitempty"`
}

// PullRequestRef is a reference to a pull request associated with a task.
type PullRequestRef struct {
	Label  string `json:"label"`
	URL    string `json:"url"`
	Status string `json:"status"`
	Repo   string `json:"repo"`
}

// ActivityEvent is a single normalized activity record.
type ActivityEvent struct {
	Action     string    `json:"action"`
	Scope      string    `json:"scope"`
	Actor      string    `json:"actor"`
	OccurredAt time.Time `json:"occurred_at"`
	Note       string    `json:"note,omitempty"`
	FeatureID  string    `json:"feature_id,omitempty"`
	TaskID     string    `json:"task_id,omitempty"`
}

// ActivityScope filters activity queries.
type ActivityScope struct {
	FeatureID string
	TaskID    string
}

// FeatureSearchQuery filters and controls workspace feature search results.
type FeatureSearchQuery struct {
	Title  string
	Status string
	Sort   string
	Page   int
	Limit  int
}

// TaskSearchQuery filters and controls task search results.
type TaskSearchQuery struct {
	TaskID string
	Title  string
	Status string
	Repo   string
	Sort   string
	Page   int
	Limit  int
}

// WorkspaceSummary is the list-view representation of a workspace.
type WorkspaceSummary struct {
	ID          string      `json:"id"`
	Name        string      `json:"name"`
	Slug        string      `json:"slug"`
	RepoURL     string      `json:"repo_url"`
	SourceState SourceState `json:"source_state"`
	UpdatedAt   time.Time   `json:"updated_at"`
}

// WorkspaceDetail is the full workspace view.
type WorkspaceDetail struct {
	WorkspaceSummary
	Features []FeatureSummary `json:"features"`
	Tasks    []TaskSummary    `json:"tasks"`
}

// FeatureSummary is the list-view representation of a feature.
type FeatureSummary struct {
	ID           string          `json:"id"`
	FeatureID    string          `json:"feature_id"`
	FeatureName  string          `json:"feature_name"`
	Title        string          `json:"title"`
	Status       string          `json:"status"`
	CurrentStage string          `json:"current_stage,omitempty"`
	Stages       json.RawMessage `json:"stages,omitempty"`
	UpdatedAt    time.Time       `json:"updated_at"`
	TaskCounts   TaskCounts      `json:"task_counts"`
}

// TaskCounts summarises task status distribution within a feature.
type TaskCounts struct {
	Total      int `json:"total"`
	Done       int `json:"done"`
	InProgress int `json:"in_progress"`
	Blocked    int `json:"blocked"`
	Ready      int `json:"ready"`
	Todo       int `json:"todo"`
}

// DocumentLink is a GitHub web URL for a feature document.
type DocumentLink struct {
	DocumentType string `json:"document_type"`
	SourcePath   string `json:"source_path"`
	URL          string `json:"url"`
}

// FeatureDetail is the full feature view.
type FeatureDetail struct {
	FeatureSummary
	WorkspaceID string          `json:"workspace_id"`
	Documents   []DocumentLink  `json:"documents"`
	Tasks       []TaskSummary   `json:"tasks"`
	Activity    []ActivityEvent `json:"activity"`
	SourceState SourceState     `json:"source_state"`
}

// TaskSummary is the list-view representation of a task.
type TaskSummary struct {
	ID            string          `json:"id"`
	TaskID        string          `json:"task_id"`
	TaskName      string          `json:"task_name"`
	FeatureID     string          `json:"feature_id"`
	FeatureName   string          `json:"feature_name"`
	Title         string          `json:"title"`
	Status        string          `json:"status"`
	Repo          string          `json:"repo,omitempty"`
	Branch        string          `json:"branch,omitempty"`
	NextAction    string          `json:"next_action,omitempty"`
	IsBlocked     bool            `json:"is_blocked"`
	BlockedReason string          `json:"blocked_reason,omitempty"`
	Pr            json.RawMessage `json:"pr"`
	WorkspacePr   json.RawMessage `json:"workspace_pr"`
}

// ExecutionContext holds execution metadata for a task.
type ExecutionContext struct {
	ActorType     string `json:"actor_type"`
	LastUpdatedBy string `json:"last_updated_by,omitempty"`
	LastUpdatedAt string `json:"last_updated_at,omitempty"`
}

// TaskDetail is the full task view.
type TaskDetail struct {
	ID            string           `json:"id"`
	TaskID        string           `json:"task_id"`
	TaskName      string           `json:"task_name"`
	FeatureID     string           `json:"feature_id"`
	FeatureName   string           `json:"feature_name"`
	Title         string           `json:"title"`
	Status        string           `json:"status"`
	Repo          string           `json:"repo,omitempty"`
	Branch        string           `json:"branch,omitempty"`
	NextAction    string           `json:"next_action,omitempty"`
	IsBlocked     bool             `json:"is_blocked"`
	BlockedReason string           `json:"blocked_reason,omitempty"`
	WorkspaceID   string           `json:"workspace_id"`
	DependsOn     []string         `json:"depends_on"`
	Execution     ExecutionContext `json:"execution"`
	PRRefs        []PullRequestRef `json:"pr_refs,omitempty"`
	Activity      []ActivityEvent  `json:"activity"`
}

// PagedFeatures is a paginated list of feature summaries.
type PagedFeatures struct {
	Items []FeatureSummary `json:"items"`
	Total int              `json:"total"`
	Page  int              `json:"page"`
	Limit int              `json:"limit"`
}

// PagedTasks is a paginated list of task summaries.
type PagedTasks struct {
	Items []TaskSummary `json:"items"`
	Total int           `json:"total"`
	Page  int           `json:"page"`
	Limit int           `json:"limit"`
}

// ImportInput is the request body for workspace import.
type ImportInput struct {
	RepoURL        string `json:"repo_url" binding:"required"`
	DefaultBranch  string `json:"default_branch"`
	Name           string `json:"name"`
	OrganizationID string `json:"organization_id"`
}

