182				return taskIDGreater(out[i].TaskName, out[j].TaskName)
183			case "task_id_asc", "":
184				return taskIDLess(out[i].TaskName, out[j].TaskName)
185			default:
186				return false
187			}
188		})
189		if filters.Limit > 0 && filters.Limit < len(out) {
190			out = out[:filters.Limit]
191		}
192		return out, nil
193	}
