200	func (f *fakeDB) SearchWorkspaceTasks(_ context.Context, _ string, filters database.TaskSearchFilters) ([]database.WorkspaceTask, error) {
201		f.searchWorkspaceTasksCalls++
202		out := make([]database.WorkspaceTask, 0, len(f.tasks))
203		for _, task := range f.tasks {
204			if filters.TaskID != "" && !strings.Contains(strings.ToLower(task.TaskName), strings.ToLower(filters.TaskID)) {
205				continue
206			}
207			if filters.Title != "" && !strings.Contains(strings.ToLower(task.Title), strings.ToLower(filters.Title)) {
208				continue
209			}
210			if filters.Status != "" && !statusMatches(task.Status, filters.Status) {
211				continue
212			}
213			if filters.Repo != "" && (task.Repo == nil || *task.Repo != filters.Repo) {
214				continue
215			}
216			out = append(out, task)
217		}
218		sort.SliceStable(out, func(i, j int) bool {
219			switch filters.Sort {
220			case "task_id_desc":
221				return taskIDGreater(out[i].TaskName, out[j].TaskName)
222			case "task_id_asc", "":
223				return taskIDLess(out[i].TaskName, out[j].TaskName)
224			default:
225				return false
226			}
227		})
228		if filters.Limit > 0 {
229			start := (filters.Page - 1) * filters.Limit
230			if filters.Page < 1 {
231				start = 0
232			}
233			if start >= len(out) {
234				return []database.WorkspaceTask{}, nil
235			}
236			end := start + filters.Limit
237			if end > len(out) {
238				end = len(out)
239			}
240			out = out[start:end]
241		}
242		return out, nil
243	}
