332	func statusMatches(status *string, filter string) bool {
333		if status == nil {
334			return false
335		}
336		for _, allowed := range strings.Split(filter, ",") {
337			if strings.TrimSpace(allowed) == *status {
338				return true
339			}
340		}
341		return false
342	}
343	
344	func taskIDLess(a, b string) bool {
345		an, aok := taskNumber(a)
346		bn, bok := taskNumber(b)
347		if aok && bok && an != bn {
348			return an < bn
349		}
350		if aok != bok {
351			return aok
352		}
353		return a < b
354	}
355	
356	func taskIDGreater(a, b string) bool {
357		an, aok := taskNumber(a)
358		bn, bok := taskNumber(b)
359		if aok && bok && an != bn {
360			return an > bn
361		}
362		if aok != bok {
363			return aok
364		}
365		return a > b
366	}
367	
368	func taskNumber(taskID string) (int, bool) {
369		if !strings.HasPrefix(taskID, "T") {
370			return 0, false
371		}
372		n, err := strconv.Atoi(strings.TrimPrefix(taskID, "T"))
373		return n, err == nil
374	}
