316	type testAPIEnvelope struct {
317		Success bool            `json:"success"`
318		Data    json.RawMessage `json:"data"`
319		Error   *testAPIError   `json:"error"`
320	}
321	
322	type testAPIError struct {
323		Code      domain.ErrorCode `json:"code"`
324		Message   string           `json:"message"`
325		Retryable bool             `json:"retryable"`
326		Source    string           `json:"source"`
327	}
328	
329	func decodeAPIData[T any](t *testing.T, body []byte) T {
330		t.Helper()
331		var envelope testAPIEnvelope
332		if err := json.Unmarshal(body, &envelope); err != nil {
333			t.Fatalf("decode response envelope: %v", err)
334		}
335		if !envelope.Success {
336			t.Fatalf("expected success envelope, got body=%s", string(body))
337		}
338		if envelope.Error != nil {
339			t.Fatalf("did not expect error field in success envelope: %+v", envelope.Error)
340		}
341		var out T
342		if err := json.Unmarshal(envelope.Data, &out); err != nil {
343			t.Fatalf("decode response data: %v", err)
344		}
345		return out
346	}
347	
348	func decodeAPIError(t *testing.T, body []byte) testAPIError {
349		t.Helper()
350		var envelope testAPIEnvelope
351		if err := json.Unmarshal(body, &envelope); err != nil {
352			t.Fatalf("decode error envelope: %v", err)
353		}
354		if envelope.Success {
355			t.Fatalf("expected error envelope, got body=%s", string(body))
356		}
357		if envelope.Error == nil {
358			t.Fatalf("expected error body, got body=%s", string(body))
359		}
360		return *envelope.Error
361	}
