382	func TestPublicResponseEnvelope_SuccessAndError(t *testing.T) {
383		ws := makeTestWorkspace()
384		r := newTestRouter(&fakeDB{workspaces: []database2.Workspace{ws}}, &fakeAdapter{})
385	
386		successRecorder := httptest.NewRecorder()
387		successReq, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "/api/workspaces", nil)
388		r.ServeHTTP(successRecorder, successReq)
389	
390		var successBody map[string]json.RawMessage
391		if err := json.Unmarshal(successRecorder.Body.Bytes(), &successBody); err != nil {
392			t.Fatalf("decode success envelope: %v", err)
393		}
394		if got := string(successBody["success"]); got != "true" {
395			t.Fatalf("expected success=true envelope, got %s body=%s", got, successRecorder.Body.String())
396		}
397		if _, ok := successBody["data"]; !ok {
398			t.Fatalf("expected success response to include data: %s", successRecorder.Body.String())
399		}
400		if _, ok := successBody["error"]; ok {
401			t.Fatalf("did not expect error field in success response: %s", successRecorder.Body.String())
402		}
403	
404		errorRecorder := httptest.NewRecorder()
405		errorReq, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "/api/workspaces/99999999-9999-9999-9999-999999999999/activity", nil)
406		r.ServeHTTP(errorRecorder, errorReq)
407	
408		var errorBody struct {
409			Success bool `json:"success"`
410			Error   struct {
411				Code      domain.ErrorCode `json:"code"`
412				Message   string           `json:"message"`
413				Retryable bool             `json:"retryable"`
414				Source    string           `json:"source"`
415			} `json:"error"`
416		}
417		if err := json.Unmarshal(errorRecorder.Body.Bytes(), &errorBody); err != nil {
418			t.Fatalf("decode error envelope: %v", err)
419		}
420		if errorBody.Success {
421			t.Fatalf("expected success=false error envelope: %s", errorRecorder.Body.String())
422		}
423		if errorBody.Error.Code != domain.ErrDatabaseNotFound {
424			t.Fatalf("expected error code %s, got %s", domain.ErrDatabaseNotFound, errorBody.Error.Code)
425		}
426		if errorBody.Error.Message == "" {
427			t.Fatal("expected error message")
428		}
429		var rawError map[string]json.RawMessage
430		if err := json.Unmarshal(errorRecorder.Body.Bytes(), &rawError); err != nil {
431			t.Fatalf("decode raw error envelope: %v", err)
432		}
433		var errorFields map[string]json.RawMessage
434		if err := json.Unmarshal(rawError["error"], &errorFields); err != nil {
435			t.Fatalf("decode raw error body: %v", err)
436		}
437		if _, ok := errorFields["source"]; !ok {
438			t.Fatalf("expected public error source field: %s", errorRecorder.Body.String())
439		}
440		if errorBody.Error.Source != string(domain.ErrorSourceDatabase) {
441			t.Fatalf("expected error source %q, got %q", domain.ErrorSourceDatabase, errorBody.Error.Source)
442		}
443	}
