// capturingAdapter records the ImportRequest passed to ImportWorkspace.
// Used to assert that the session OrganizationID (not the body value) reaches the adapter.
type capturingAdapter struct {
	captured adapter.ImportRequest
	importID string
}

func (c *capturingAdapter) ImportWorkspace(_ context.Context, req adapter.ImportRequest) (string, error) {
	c.captured = req
	return c.importID, nil
}
func (c *capturingAdapter) SyncWorkspace(_ context.Context, _ string) error { return nil }

// TestImportWorkspace_SessionOrganizationIDOverridesBodyValue proves that the
// handler discards the client-supplied organization_id and replaces it with the
// value from the authenticated session context before forwarding to the adapter.
// The session is always authoritative; the body value is ignored.
func TestImportWorkspace_SessionOrganizationIDOverridesBodyValue(t *testing.T) {
