// Package service implements the WorkspaceService that orchestrates read queries
// and RPC calls to adapter-service.
package service

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/tiendv89/workflow-backend/internal/adapter"
	database2 "github.com/tiendv89/workflow-backend/internal/database"
	"github.com/tiendv89/workflow-backend/internal/domain"
)

// DatabaseReader is the read-only interface over the shared PostgreSQL schema.
type DatabaseReader interface {
	ListWorkspaces(ctx context.Context) ([]database2.Workspace, error)
	GetWorkspace(ctx context.Context, workspaceID string) (database2.Workspace, error)
	GetWorkspaceUnscoped(ctx context.Context, workspaceID string) (database2.Workspace, error)
	GetGitHubSource(ctx context.Context, workspaceID string) (database2.WorkspaceGitHubSource, error)
	ListGitHubSources(ctx context.Context) ([]database2.WorkspaceGitHubSource, error)
	ListLatestSyncRunsPerWorkspace(ctx context.Context) ([]database2.WorkspaceSyncRun, error)
	GetLatestSyncRun(ctx context.Context, workspaceID string) (database2.WorkspaceSyncRun, error)
	ListWorkspaceFeatures(ctx context.Context, workspaceID string) ([]database2.WorkspaceFeature, error)
	SearchWorkspaceFeatures(ctx context.Context, workspaceID string, filters database2.FeatureSearchFilters) ([]database2.WorkspaceFeature, error)
	CountWorkspaceFeatures(ctx context.Context, workspaceID string, filters database2.FeatureSearchFilters) (int, error)
	ListFeatureTaskCounts(ctx context.Context, workspaceID string, featureIDs []string) ([]database2.WorkspaceFeatureTaskCounts, error)
	GetWorkspaceFeature(ctx context.Context, workspaceID, featureID string) (database2.WorkspaceFeature, error)
	ListFeatureDocuments(ctx context.Context, workspaceID, featureID string) ([]database2.WorkspaceFeatureDocument, error)
	ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]database2.WorkspaceTask, error)
	SearchFeatureTasks(ctx context.Context, workspaceID, featureID string, filters database2.TaskSearchFilters) ([]database2.WorkspaceTask, error)
	CountFeatureTasks(ctx context.Context, workspaceID, featureID string, filters database2.TaskSearchFilters) (int, error)
	SearchWorkspaceTasks(ctx context.Context, workspaceID string, filters database2.TaskSearchFilters) ([]database2.WorkspaceTask, error)
	CountWorkspaceTasks(ctx context.Context, workspaceID string, filters database2.TaskSearchFilters) (int, error)
	ListWorkspaceTasks(ctx context.Context, workspaceID string) ([]database2.WorkspaceTask, error)
	GetWorkspaceTask(ctx context.Context, workspaceID, featureID, taskID string) (database2.WorkspaceTask, error)
	GetWorkspaceTaskByID(ctx context.Context, workspaceID, taskID string) (database2.WorkspaceTask, error)
	ListActivityEvents(ctx context.Context, workspaceID, featureID, taskID string) ([]database2.WorkspaceActivityEvent, error)
}

// AdapterCaller issues RPC calls to adapter-service for write operations.
type AdapterCaller interface {
	ImportWorkspace(ctx context.Context, req adapter.ImportRequest) (string, error)
	SyncWorkspace(ctx context.Context, workspaceID string) error
}

// WorkspaceService orchestrates reads from PostgreSQL and calls to adapter-service.
type WorkspaceService struct {
	db             DatabaseReader
	adapter        AdapterCaller
	staleThreshold time.Duration
}

// New creates a new WorkspaceService.
func New(db DatabaseReader, adapterClient AdapterCaller, staleThreshold time.Duration) *WorkspaceService {
	return &WorkspaceService{
		db:             db,
		adapter:        adapterClient,
		staleThreshold: staleThreshold,
	}
}

// ListWorkspaces returns summary rows for all saved workspaces with source state.
func (s *WorkspaceService) ListWorkspaces(ctx context.Context) ([]domain.WorkspaceSummary, error) {
	rows, err := s.db.ListWorkspaces(ctx)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	// Batch-load latest sync run per workspace to avoid N+1 queries.
	allRuns, err := s.db.ListLatestSyncRunsPerWorkspace(ctx)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	runMap := make(map[string]database2.WorkspaceSyncRun, len(allRuns))
	for _, run := range allRuns {
		runMap[database2.UUIDString(run.WorkspaceID)] = run
	}

	// Batch-load GitHub sources to avoid N+1 queries.
	allSrcs, err := s.db.ListGitHubSources(ctx)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	srcMap := make(map[string]string, len(allSrcs))
	for _, src := range allSrcs {
		srcMap[database2.UUIDString(src.WorkspaceID)] = src.RepoURL
	}

	out := make([]domain.WorkspaceSummary, 0, len(rows))
	for _, r := range rows {
		wsID := database2.UUIDString(r.ID)
		srcRun, ok := runMap[wsID]
		var ss domain.SourceState
		if ok {
			ss = toSourceState(&srcRun, s.staleThreshold)
		} else {
			ss = domain.DeriveSourceState(nil, s.staleThreshold)
		}

		repoURL := srcMap[wsID]
		out = append(out, domain.WorkspaceSummary{
			ID:          wsID,
			Name:        r.Name,
			Slug:        r.Slug,
			RepoURL:     repoURL,
			SourceState: ss,
			UpdatedAt:   r.UpdatedAt.Time,
		})
	}
	return out, nil
}

// ImportWorkspace calls adapter-service to import/persist a workspace, then
// returns the normalized persisted detail from PostgreSQL.
//
// The post-import fetch uses an unscoped read because the session's accessible
// workspace-ID snapshot was taken before this workspace existed. Authorization
// is enforced by verifying the persisted organization_id matches the session's
// organization_id; any mismatch yields a 404 (DATABASE_NOT_FOUND) to preserve
// cross-tenant isolation.
func (s *WorkspaceService) ImportWorkspace(ctx context.Context, input domain.ImportInput) (*domain.WorkspaceDetail, domain.SourceError) {
	workspaceID, err := s.adapter.ImportWorkspace(ctx, adapter.ImportRequest{
		RepoURL:        input.RepoURL,
		DefaultBranch:  input.DefaultBranch,
		Name:           input.Name,
		OrganizationID: input.OrganizationID,
	})
	if err != nil {
		if se, ok := err.(domain.SourceError); ok {
			return nil, se
		}
		return nil, domain.NewAdapterError(domain.ErrAdapterInternal, err.Error())
	}

	ws, dbErr := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if dbErr != nil {
		if errors.Is(dbErr, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, dbErr.Error())
	}

	// if ac, ok := authmw.FromContext(ctx); ok && ac.OrganizationID != "" {
	// 	if database2.UUIDString(ws.OrganizationID) != ac.OrganizationID {
	// 		return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
	// 	}
	// }

	return s.buildWorkspaceDetail(ctx, ws)
}

// GetWorkspaceSummary returns only basic workspace information without loading features/tasks.
func (s *WorkspaceService) GetWorkspaceSummary(ctx context.Context, workspaceID string) (*domain.WorkspaceSummary, domain.SourceError) {
	ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	wsID := database2.UUIDString(ws.ID)
	syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
	var ss domain.SourceState
	if errors.Is(err, database2.ErrNotFound) || err != nil {
		ss = domain.DeriveSourceState(nil, s.staleThreshold)
	} else {
		ss = toSourceState(&syncRun, s.staleThreshold)
	}

	return &domain.WorkspaceSummary{
		ID:          wsID,
		Name:        ws.Name,
		Slug:        ws.Slug,
		RepoURL:     s.githubRepoURL(ctx, wsID),
		SourceState: ss,
		UpdatedAt:   ws.UpdatedAt.Time,
	}, domain.SourceError{}
}

// GetWorkspace returns full workspace detail with features, tasks, and source state.
func (s *WorkspaceService) GetWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError) {
	ws, se := s.fetchWorkspace(ctx, workspaceID)
	if se != (domain.SourceError{}) {
		return nil, se
	}
	return s.buildWorkspaceDetail(ctx, ws)
}

// fetchWorkspace resolves a workspace row with scoped access control, falling back
// to an unscoped read with org_id authorization for sessions whose accessible-set
// snapshot predates the workspace (e.g. immediately after import).
func (s *WorkspaceService) fetchWorkspace(ctx context.Context, workspaceID string) (database2.Workspace, domain.SourceError) {
	ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err == nil {
		return ws, domain.SourceError{}
	}
	if !errors.Is(err, database2.ErrNotFound) {
		return database2.Workspace{}, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	// ac, ok := authmw.FromContext(ctx)
	// if !ok || ac.OrganizationID == "" {
	// 	return database2.Workspace{}, domain.NewDatabaseNotFound("workspace", workspaceID)
	// }
	ws, err = s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return database2.Workspace{}, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return database2.Workspace{}, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	// if database2.UUIDString(ws.OrganizationID) != ac.OrganizationID {
	// 	return database2.Workspace{}, domain.NewDatabaseNotFound("workspace", workspaceID)
	// }
	return ws, domain.SourceError{}
}

// buildWorkspaceDetail assembles the full WorkspaceDetail from an already-fetched
// Workspace row. The caller is responsible for authorizing access to ws.
func (s *WorkspaceService) buildWorkspaceDetail(ctx context.Context, ws database2.Workspace) (*domain.WorkspaceDetail, domain.SourceError) {
	wsID := database2.UUIDString(ws.ID)

	features, err := s.db.ListWorkspaceFeatures(ctx, wsID)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	tasks, err := s.db.ListWorkspaceTasks(ctx, wsID)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	taskCountsByFeature := countTasksByFeature(tasks)

	syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
	var ss domain.SourceState
	if errors.Is(err, database2.ErrNotFound) || err != nil {
		ss = domain.DeriveSourceState(nil, s.staleThreshold)
	} else {
		ss = toSourceState(&syncRun, s.staleThreshold)
	}

	featureSummaries := make([]domain.FeatureSummary, 0, len(features))
	for _, f := range features {
		counts := taskCountsByFeature[database2.UUIDString(f.FeatureID)]
		featureSummaries = append(featureSummaries, domain.FeatureSummary{
			ID:           database2.UUIDString(f.ID),
			FeatureID:    database2.UUIDString(f.FeatureID),
			FeatureName:  f.FeatureName,
			Title:        f.Title,
			Status:       derefStr(f.FeatureStatus),
			CurrentStage: derefStr(f.CurrentStage),
			Stages:       rawJSONOrNil(f.Stages),
			UpdatedAt:    f.UpdatedAt.Time,
			TaskCounts:   counts,
		})
	}

	taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
	for _, t := range tasks {
		taskSummaries = append(taskSummaries, toTaskSummary(t))
	}

	repoURL := s.githubRepoURL(ctx, wsID)
	return &domain.WorkspaceDetail{
		WorkspaceSummary: domain.WorkspaceSummary{
			ID:          wsID,
			Name:        ws.Name,
			Slug:        ws.Slug,
			RepoURL:     repoURL,
			SourceState: ss,
			UpdatedAt:   ws.UpdatedAt.Time,
		},
		Features: featureSummaries,
		Tasks:    taskSummaries,
	}, domain.SourceError{}
}

// SyncWorkspace calls adapter-service to re-sync a workspace then returns updated detail.
// On sync failure with cached data, returns cached data marked stale.
// On sync failure without cached data, returns a structured source error.
func (s *WorkspaceService) SyncWorkspace(ctx context.Context, workspaceID string) (*domain.WorkspaceDetail, domain.SourceError) {
	if _, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID); err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	if err := s.adapter.SyncWorkspace(ctx, workspaceID); err != nil {
		// Sync failed — try to return cached data with stale marker.
		detail, dbErr := s.GetWorkspace(ctx, workspaceID)
		if dbErr != (domain.SourceError{}) {
			// No cached data — return the adapter error.
			if se, ok := err.(domain.SourceError); ok {
				return nil, se
			}
			return nil, domain.NewAdapterError(domain.ErrAdapterInternal, err.Error())
		}
		// Return stale cached data.
		detail.SourceState.Stale = true
		if se, ok := err.(domain.SourceError); ok {
			detail.SourceState.ErrorCode = string(se.Code)
			detail.SourceState.ErrorMessage = se.Message
		}
		return detail, domain.SourceError{}
	}

	return s.GetWorkspace(ctx, workspaceID)
}

// GetFeature returns feature detail with documents, tasks, and activity.
func (s *WorkspaceService) GetFeature(ctx context.Context, workspaceID, featureID string) (*domain.FeatureDetail, domain.SourceError) {
	// Verify workspace exists.
	ws, err := s.db.GetWorkspaceUnscoped(ctx, workspaceID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("workspace", workspaceID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	wsID := database2.UUIDString(ws.ID)

	feat, err := s.db.GetWorkspaceFeature(ctx, wsID, featureID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("feature", featureID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	featureUUID := database2.UUIDString(feat.FeatureID)

	docs, err := s.db.ListFeatureDocuments(ctx, wsID, featureUUID)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	tasks, err := s.db.ListFeatureTasks(ctx, wsID, featureUUID)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	activity, err := s.db.ListActivityEvents(ctx, wsID, featureUUID, "")
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	syncRun, err := s.db.GetLatestSyncRun(ctx, wsID)
	var ss domain.SourceState
	if errors.Is(err, database2.ErrNotFound) || err != nil {
		ss = domain.DeriveSourceState(nil, s.staleThreshold)
	} else {
		ss = toSourceState(&syncRun, s.staleThreshold)
	}

	counts := countTasks(tasks)
	docLinks := make([]domain.DocumentLink, 0, len(docs))
	for _, d := range docs {
		docLinks = append(docLinks, domain.DocumentLink{
			DocumentType: d.DocumentType,
			SourcePath:   d.SourcePath,
			URL:          derefStr(d.URL),
		})
	}

	taskSummaries := make([]domain.TaskSummary, 0, len(tasks))
	for _, t := range tasks {
		taskSummaries = append(taskSummaries, toTaskSummary(t))
	}

	activityEvents := make([]domain.ActivityEvent, 0, len(activity))
	for _, a := range activity {
		activityEvents = append(activityEvents, toActivityEvent(a))
	}

	return &domain.FeatureDetail{
		FeatureSummary: domain.FeatureSummary{
			ID:           database2.UUIDString(feat.ID),
			FeatureID:    database2.UUIDString(feat.FeatureID),
			FeatureName:  feat.FeatureName,
			Title:        feat.Title,
			Status:       derefStr(feat.FeatureStatus),
			CurrentStage: derefStr(feat.CurrentStage),
			Stages:       rawJSONOrNil(feat.Stages),
			UpdatedAt:    feat.UpdatedAt.Time,
			TaskCounts:   counts,
		},
		WorkspaceID: workspaceID,
		Documents:   docLinks,
		Tasks:       taskSummaries,
		Activity:    activityEvents,
		SourceState: ss,
	}, domain.SourceError{}
}

// ListFeatureTasks returns task summaries for all tasks in a feature.
func (s *WorkspaceService) ListFeatureTasks(ctx context.Context, workspaceID, featureID string) ([]domain.TaskSummary, domain.SourceError) {
	feat, err := s.db.GetWorkspaceFeature(ctx, workspaceID, featureID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("feature", featureID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	tasks, err := s.db.ListFeatureTasks(ctx, workspaceID, database2.UUIDString(feat.FeatureID))
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	out := make([]domain.TaskSummary, 0, len(tasks))
	for _, t := range tasks {
		out = append(out, toTaskSummary(t))
	}
	return out, domain.SourceError{}
}

// SearchTasks returns paged task summaries for a feature filtered by search/task_id/title/status/repo.
func (s *WorkspaceService) SearchTasks(ctx context.Context, workspaceID, featureID string, query domain.TaskSearchQuery) (*domain.PagedTasks, domain.SourceError) {
	if query.Page == 0 {
		query.Page = 1
	}
	if query.Page < 1 {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "page must be greater than or equal to 1")
	}
	if query.Limit < 0 {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "limit must be greater than or equal to 0")
	}
	if query.Sort != "" && !isValidTaskSearchSort(query.Sort) {
		return nil, domain.NewValidationError(domain.ErrValidationInvalidQuery, "sort must be one of task_id_asc, task_id_desc, title_asc, title_desc, status_asc, status_desc, repo_asc, repo_desc, updated_at_asc, updated_at_desc, time_asc, time_desc, createdAt, -createdAt")
	}

	feat, err := s.db.GetWorkspaceFeature(ctx, workspaceID, featureID)
	if err != nil {
		if errors.Is(err, database2.ErrNotFound) {
			return nil, domain.NewDatabaseNotFound("feature", featureID)
		}
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	featureUUID := database2.UUIDString(feat.FeatureID)

	filters := database2.TaskSearchFilters{
		TaskID: query.TaskID,
		Title:  query.Title,
		Status: query.Status,
		Repo:   query.Repo,
		Sort:   query.Sort,
		Page:   query.Page,
		Limit:  query.Limit,
	}
	tasks, err := s.db.SearchFeatureTasks(ctx, workspaceID, featureUUID, filters)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}
	total, err := s.db.CountFeatureTasks(ctx, workspaceID, featureUUID, filters)
	if err != nil {
		return nil, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error())
	}

	items := make([]domain.TaskSummary, 0, len(tasks))
	for _, t := range tasks {
		items = append(items, toTaskSummary(t))
	}
	return &domain.PagedTasks{Items: items, Total: total, Page: query.Page, Limit: query.Limit}, domain.SourceError{}
